<?php
 namespace Pterodactyl\Services\Dezerx\Subdomains; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Log; class SubdomainManager { public function __construct(private readonly CloudflareClient $cloudflare) { } public const NAME = '/^[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])?$/'; public function domains(?Server $server = null): array { $egg = $server === null ? null : (int) $server->egg_id; return DB::table('dezerx_subdomain_domains') ->where('enabled', true) ->orderBy('domain') ->get() ->filter(fn ($row) => $egg === null || self::servesEgg($row->eggs ?? null, $egg)) ->map(fn ($row) => [ 'id' => (int) $row->id, 'domain' => (string) $row->domain, 'recordType' => (string) $row->record_type, ]) ->values() ->all(); } public function offersAny(): bool { return DB::table('dezerx_subdomain_domains')->where('enabled', true)->exists(); } public static function servesEgg(?string $eggs, int $egg): bool { $allowed = json_decode((string) $eggs, true); if (!is_array($allowed) || $allowed === []) { return true; } return in_array($egg, array_map('intval', $allowed), true); } public static function recordsFor(int $server): array { return DB::table('dezerx_subdomain_records as r') ->leftJoin('dezerx_subdomain_domains as d', 'd.id', '=', 'r.domain_id') ->where('r.server_id', $server) ->orderByDesc('r.created_at') ->get(['r.id', 'r.subdomain', 'r.record_type', 'r.port', 'r.target', 'd.domain']) ->map(fn ($row) => [ 'id' => (int) $row->id, 'name' => $row->subdomain . '.' . ($row->domain ?? '?'), 'type' => (string) $row->record_type, 'target' => (string) $row->target, 'port' => $row->port ? (int) $row->port : null, ]) ->all(); } public function claim(int $domainId, string $subdomain, Server $server, ?int $userId, string $target, int $port): array { $subdomain = strtolower(trim($subdomain)); if (preg_match(self::NAME, $subdomain) !== 1) { return ['ok' => false, 'message' => 'Use letters, numbers and hyphens only.']; } $domain = DB::table('dezerx_subdomain_domains')->where('id', $domainId)->first(); if ($domain === null || !$domain->enabled) { return ['ok' => false, 'message' => 'That domain is not available.']; } if (!self::servesEgg($domain->eggs ?? null, (int) $server->egg_id)) { return ['ok' => false, 'message' => 'That domain is not offered for this kind of server.']; } $used = DB::table('dezerx_subdomain_records')->where('server_id', $server->id)->count(); if ($used >= Subdomains::maxPerServer()) { return ['ok' => false, 'message' => 'This server already has as many names as it is allowed.']; } $exists = DB::table('dezerx_subdomain_records') ->where('domain_id', $domainId) ->where('subdomain', $subdomain) ->exists(); if ($exists) { return ['ok' => false, 'message' => 'That name is already taken.']; } $zone = $this->cloudflare->zoneId((string) $domain->domain); if ($zone === null) { return ['ok' => false, 'message' => 'Cloudflare could not be reached for that domain.']; } $host = $subdomain . '.' . $domain->domain; if ($this->cloudflare->records($zone, 'A', $host) !== [] || $this->cloudflare->records($zone, 'AAAA', $host) !== [] || $this->cloudflare->records($zone, 'CNAME', $host) !== []) { return ['ok' => false, 'message' => 'That name already exists in DNS.']; } $kind = match (true) { filter_var($target, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) !== false => 'A', filter_var($target, FILTER_VALIDATE_IP, FILTER_FLAG_IPV6) !== false => 'AAAA', default => 'CNAME', }; $made = $this->cloudflare->create($zone, [ 'type' => $kind, 'name' => $host, 'content' => $target, 'proxied' => false, 'ttl' => 120, ]); if (!$made['ok']) { return ['ok' => false, 'message' => $made['error'] ?? 'Cloudflare refused the record.']; } $type = $kind; $helper = null; $joinable = $host . ':' . $port; if (strtoupper((string) $domain->record_type) === 'SRV') { $protocol = trim((string) $domain->protocol) ?: '_minecraft'; $transport = trim((string) $domain->transport) ?: 'tcp'; $srv = $this->cloudflare->create($zone, [ 'type' => 'SRV', 'name' => $protocol . '._' . $transport . '.' . $host, 'data' => [ 'priority' => 1, 'weight' => 1, 'port' => $port, 'target' => $host, ], 'ttl' => 120, ]); if (!$srv['ok']) { $this->cloudflare->delete($zone, (string) $made['id']); return ['ok' => false, 'message' => $srv['error'] ?? 'Cloudflare refused the service record.']; } $type = 'SRV'; $helper = $made['id']; $made = $srv; $joinable = $host; } DB::table('dezerx_subdomain_records')->insert([ 'domain_id' => $domainId, 'user_id' => $userId, 'server_id' => $server->id, 'subdomain' => $subdomain, 'record_type' => $type, 'record_id' => $made['id'], 'helper_record_id' => $helper, 'target' => $target, 'port' => $port, 'created_at' => now(), 'updated_at' => now(), ]); return ['ok' => true, 'message' => $joinable]; } public function release(int $id, ?int $server = null): array { $query = DB::table('dezerx_subdomain_records')->where('id', $id); if ($server !== null) { $query->where('server_id', $server); } $record = $query->first(); if ($record === null) { return ['ok' => false, 'message' => 'That name is not registered here.']; } $domain = DB::table('dezerx_subdomain_domains')->where('id', $record->domain_id)->first(); $this->purge($domain === null ? null : (string) $domain->domain, $record->record_id, $record->helper_record_id ?? null); DB::table('dezerx_subdomain_records')->where('id', $id)->delete(); return ['ok' => true, 'message' => 'Released.']; } public function heldBy(int $server): array { return DB::table('dezerx_subdomain_records as r') ->leftJoin('dezerx_subdomain_domains as d', 'd.id', '=', 'r.domain_id') ->where('r.server_id', $server) ->get(['r.subdomain', 'r.record_id', 'r.helper_record_id', 'd.domain']) ->map(fn ($row) => [ 'host' => $row->subdomain . '.' . ($row->domain ?? '?'), 'domain' => $row->domain === null ? null : (string) $row->domain, 'record' => $row->record_id, 'helper' => $row->helper_record_id, ]) ->all(); } public function forget(array $held): void { foreach ($held as $entry) { try { if ($this->purge($entry['domain'], $entry['record'], $entry['helper'])) { continue; } Log::warning('Cloudflare kept a subdomain belonging to a deleted server', [ 'host' => $entry['host'], 'record' => $entry['record'], 'helper' => $entry['helper'], ]); } catch (\Throwable $exception) { Log::warning('A subdomain could not be handed back to Cloudflare', [ 'host' => $entry['host'], 'record' => $entry['record'], 'helper' => $entry['helper'], 'error' => $exception->getMessage(), ]); } } } private function purge(?string $domain, ?string $record, ?string $helper): bool { $remotes = array_values(array_filter([$record, $helper])); if ($remotes === []) { return true; } $zone = $domain === null ? null : $this->cloudflare->zoneId($domain); if ($zone === null) { return false; } $clean = true; foreach ($remotes as $remote) { if (!$this->cloudflare->delete($zone, (string) $remote)) { $clean = false; } } return $clean; } } 